function F({registerIndicator:w,sourceValues:d,nulls:y}){const g=o=>{const l=new Array(o).fill(0);let r=0,i=1;for(let e=0;e<o;e++){const n=e===0||e===1?1:i+r;l[o-1-e]=n,r=i,i=n}return l};w({id:"oa-fwma",name:"Fibonacci Weighted Moving Average (FWMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1,tooltip:"Number of Fibonacci weights in the window."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"fwma",type:"line",title:"FWMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,l){const r=Math.max(1,Math.floor(Number(l.period)||10)),i=d(o,l.source??"close"),e=o.length,n=new Array(e).fill(NaN);let a=null,u=-1;for(let t=0;t<e;t++){const c=Math.min(t+1,r);c!==u&&(a=g(c),u=c);let f=0,m=0;for(let s=0;s<c;s++){const b=i[t-s];if(!Number.isFinite(b))continue;const h=a[s];f+=b*h,m+=h}const p=f/m;Number.isFinite(p)?n[t]=p:Number.isFinite(i[t])&&(n[t]=i[t])}return{fwma:y(n)}}})}export{F as default};
